import { useEffect, useState } from 'react'
import { Apple, ArrowLeft, ArrowRight, AtSign, Bell, CalendarDays, Camera, Carrot, ChartNoAxesCombined, ChevronDown, CircleCheck, Clock, Eye, Flag, Globe, Heart, House, ImagePlus, Leaf, Lock, LogOut, Mail, Map, MapPin, MessageCircle, MilkOff, Navigation, Phone, Search, Settings, Share2, ShieldCheck, ShoppingBasket, SlidersHorizontal, Soup, Sparkles, Star, Store, Ticket, UserRound, Vegan, WheatOff, X } from 'lucide-react'
import './App.css'

const categories = [['Vegano', Vegan], ['Vegetariano', Leaf], ['Sem glúten', WheatOff], ['Sem lactose', MilkOff], ['Mercados', Store]]
const topPlaces = [
  ['Raízes Bistrô Vegano', '4,9', '(128)', 'Batel · 1,2 km', ['Vegano', 'Sem glúten'], 'leaf', 'Verificado pela comunidade'],
  ['Casa Girassol', '4,6', '(94)', 'Juvevê · 2,1 km', ['Vegetariano', 'Sem lactose'], 'sun', 'Perfil da comunidade'],
  ['Lótus Ramen', '4,5', '(76)', 'Centro · 2,8 km', ['Opções veganas'], 'leaf', 'Perfil da comunidade'],
]
const nearby = [
  ['Café Abacate', '4,8', '(62)', 'Água Verde · 900 m', ['Vegetariano', 'Sem lactose'], 'leaf'],
  ['Empório Grão Livre', '4,4', '(51)', 'Batel · 1,6 km', ['Sem lactose', 'Vegano'], 'peach'],
  ['Trattoria Verde', '4,6', '(83)', 'Centro · 2,4 km', ['Opções veganas'], 'sun'],
]

function Art({ tone }) { return <div className={`art ${tone}`}><Soup size={42} strokeWidth={1.5} /></div> }
function Rating({ rating, count }) { return <div className="rating"><span>★★★★★</span><b>{rating}</b><em>{count}</em></div> }
function Tags({ tags }) { return <div className="tags">{tags.map(t => <i className={t.includes('glúten') ? 'warm' : ''} key={t}>{t}</i>)}</div> }
function ListCard({ data, saved, save, open }) { const [name, rating, count, meta, tags, tone, trust] = data; return <article className="list-card" onClick={open}><div className="media"><Art tone={tone}/><mark><Star size={15} fill="currentColor"/></mark></div><div className="card-copy"><h3>{name}</h3><Rating rating={rating} count={count}/><p>{meta}</p><Tags tags={tags}/><small><UserRound size={14}/>{trust}</small></div><button className={`heart mini ${saved ? 'saved' : ''}`} onClick={e => {e.stopPropagation();save()}} aria-label={`Favoritar ${name}`}><Heart size={19} fill={saved ? 'currentColor' : 'none'}/></button></article> }
function CarouselCard({ data, saved, save }) { const [name, rating, count, meta, tags, tone] = data; return <article className="carousel-card"><div className="hero"><Art tone={tone}/><button className={`heart ${saved ? 'saved' : ''}`} onClick={save} aria-label={`Favoritar ${name}`}><Heart size={19} fill={saved ? 'currentColor' : 'none'}/></button></div><div className="carousel-copy"><h3>{name}</h3><Rating rating={rating} count={count}/><p>{meta}</p><Tags tags={tags}/></div></article> }
function Splash() { return <div className="splash"><div className="produce" aria-hidden="true"><div className="splash-bg"><ShoppingBasket size={56}/></div><Apple className="splash-apple" size={26}/><Soup className="splash-bowl" size={28}/><Carrot className="splash-carrot" size={22}/></div><strong>Vegetar</strong><p>Encontrando sabores que combinam com você</p><aside><b/><b/><b/></aside></div> }
function StarPicker({ value, setValue }) { return <div className="star-picker">{[1,2,3,4,5].map(n => <button type="button" onClick={() => setValue(n)} aria-label={`${n} estrelas`} key={n}><Star fill={n <= value ? 'currentColor' : 'none'}/></button>)}</div> }
function Review({ back, submitted }) { const [rating,setRating]=useState(4); const [criteria,setCriteria]=useState([5,4,0]); const [text,setText]=useState(''); const [restrictions,setRestrictions]=useState(['Vegano','Sem glúten']); const toggleTag=t=>setRestrictions(x=>x.includes(t)?x.filter(i=>i!==t):[...x,t]); const rows=[['Existência de pratos','Havia opções adequadas e bem identificadas.'],['Contaminação cruzada','O preparo pareceu seguro para sua restrição.'],['Flexibilidade do chef','A equipe conseguiu adaptar os pratos.']]; return <main className="shell"><section className="phone review-page"><header className="form-top"><button onClick={back} aria-label="Voltar"><ArrowLeft/></button><h2>Adicionar avaliação</h2><span/></header><div className="review-scroll"><section className="review-place"><Art tone="leaf"/><div><b>Raízes Bistrô Vegano</b><small>São Francisco · Curitiba</small></div></section><aside className="email-notice"><Mail/><p>Você está avaliando como <b>marina@email.com</b>. Seu e-mail não será exibido publicamente.</p></aside><section className="form-section"><h3>Nota geral</h3><StarPicker value={rating} setValue={setRating}/><b className="rating-label">{rating === 5 ? 'Excelente' : rating === 4 ? 'Muito bom' : rating === 3 ? 'Bom' : rating === 2 ? 'Regular' : 'Avalie sua experiência'}</b></section><section className="form-section"><h3>Avalie por critério</h3><p className="section-copy">Seu relato ajuda outras pessoas com restrições alimentares.</p>{rows.map(([title,help],i)=><div className="criteria" key={title}><b>{title}</b><small>{help}</small><StarPicker value={criteria[i]} setValue={v=>setCriteria(x=>x.map((n,j)=>j===i?v:n))}/></div>)}</section><section className="form-section"><h3>Conte como foi</h3><label>Seu comentário<textarea value={text} onChange={e=>setText(e.target.value)} placeholder="O que você pediu? Como foi o atendimento? Conte detalhes que podem ajudar a comunidade."/></label><small className="field-help">Opcional · até 500 caracteres</small></section><section className="form-section"><h3>Fotos</h3><p className="section-copy">Fotos ajudam a comunidade a conhecer o local.</p><div className="photo-add"><button><Camera/><span>Adicionar foto</span></button><div><Art tone="leaf"/></div><div><Art tone="sun"/></div></div><aside className="photo-notice"><ShieldCheck/>Fotos comprovam sua experiência e ajudam a manter as informações confiáveis.</aside></section><section className="form-section"><h3>Restrições atendidas</h3><p className="section-copy">Selecione apenas o que foi atendido na sua visita.</p><div className="select-tags">{['Vegano','Vegetariano','Sem glúten','Sem lactose','Amendoim','Oleaginosas','Frutos do mar','Ovo','Soja'].map(tag=><button onClick={()=>toggleTag(tag)} className={restrictions.includes(tag)?'selected':''} key={tag}>{tag}</button>)}</div></section><section className="form-section date-section"><h3>Data da visita</h3><label>Quando você visitou?<span className="date-input"><CalendarDays/><input type="date" defaultValue="2026-11-08"/></span></label></section><aside className="limit-notice">Você pode publicar até 3 avaliações por dia para preservar a qualidade da comunidade.</aside></div><footer className="submit-bar"><button onClick={submitted}>Enviar avaliação</button></footer></section></main> }
function ReviewSent({ restaurant, home }) { return <main className="shell"><section className="phone sent-page"><div className="sent-content"><div className="sent-art"><div><CircleCheck size={54}/></div><Apple size={25}/><Carrot size={24}/><Leaf size={23}/></div><h1>Avaliação enviada!</h1><p>Obrigada por compartilhar sua experiência. Seu relato ajuda a comunidade a fazer escolhas mais seguras.</p></div><footer className="sent-actions"><button onClick={restaurant}>Voltar ao restaurante</button><button onClick={home}>Avaliar outro lugar</button></footer></section></main> }
function ReportModal({ close }) { const [reason,setReason]=useState('Conflito de interesse'); const [sent,setSent]=useState(false); if(sent) return <div className="modal-layer"><section className="report-modal report-success"><button className="modal-close" onClick={close} aria-label="Fechar"><X/></button><span className="success-icon"><CircleCheck/></span><h2>Denúncia recebida</h2><h3>Vamos analisar em até 7 dias</h3><p>Obrigado por cuidar da comunidade. Nossa equipe avaliará esta denúncia conforme as diretrizes do Vegetar.</p><button className="primary-modal" onClick={close}>Entendi</button></section></div>; return <div className="modal-layer"><section className="report-modal"><header><h2>Denunciar avaliação</h2><button className="modal-close" onClick={close} aria-label="Fechar"><X/></button></header><p>Por que você quer denunciar esta avaliação?</p><div className="report-options">{['Ofensa ou discurso de ódio','Expõe dado pessoal','Conflito de interesse','Informação falsa','Spam ou propaganda'].map(item=><label key={item}><input type="radio" checked={reason===item} onChange={()=>setReason(item)}/><span/>{item}</label>)}</div><label className="report-detail">Conte mais (opcional)<input placeholder="Descreva o problema"/></label><div className="report-actions"><button className="primary-modal" onClick={()=>setSent(true)}>Enviar denúncia</button><button onClick={close}>Cancelar</button></div></section></div> }
function DetailWithReport({ back, review }) { const [reporting,setReporting]=useState(false); return <><Detail back={back} review={review}/><button className="report-launcher" onClick={()=>setReporting(true)}><Flag/>Denunciar avaliação</button>{reporting&&<ReportModal close={()=>setReporting(false)}/>}</> }
function Home6({ login, detail, profile }) { return <main className="shell"><section className="phone home6"><header><button className="location"><MapPin size={22}/><span><small>Você está em</small><b>Curitiba <ChevronDown size={16}/></b></span></button><button className="login" onClick={login}><UserRound size={20}/>Entrar</button></header><button className="home-search"><Search/><span><b>Encontre seu próximo sabor</b><small>Restaurantes, mercados e empórios</small></span></button><nav className="chips">{categories.slice(0,4).map(([label,Icon])=><button key={label}><Icon size={21}/>{label}</button>)}</nav><div className="home6-scroll"><section><div className="heading"><div><h2>Top restaurantes</h2><p>Mais amados pela comunidade</p></div></div><button className="home-place" onClick={detail}><Art tone="leaf"/><span><b>Raízes Bistrô Vegano</b><Rating rating="4,9" count="(128)"/><small>Batel · 1,2 km</small><Tags tags={['Vegano','Sem glúten']}/></span><Heart/></button></section><section><div className="heading"><div><h2>Hits perto de você</h2><p>Opções para descobrir hoje</p></div></div><div className="mini-cards"><Art tone="sun"/><Art tone="peach"/></div></section></div><nav className="tabs"><button className="active"><House/>Início</button><button><Map/>Mapa</button><button><Heart/>Favoritos</button><button onClick={profile}><UserRound/>Perfil</button></nav></section></main> }
function AuthFrame({ title, subtitle, back, children }) { return <main className="shell"><section className="phone auth-page"><header className="auth-top"><button onClick={back}><ArrowLeft/></button><div className="auth-logo"><Leaf/>Vegetar</div><span/></header><div className="auth-body"><h1>{title}</h1><p>{subtitle}</p>{children}</div></section></main> }
function Login({ back, success, signup, reset, errors, restaurant }) { const [error,setError]=useState(false); return <AuthFrame title="Que bom te ver!" subtitle="Entre para salvar seus lugares e compartilhar avaliações." back={back}><label className="auth-field">E-mail<span><Mail/><input defaultValue="marina@email.com" type="email"/></span></label><label className="auth-field">Senha<span><Lock/><input type="password" defaultValue="senha"/></span></label>{error&&<aside className="auth-error">E-mail ou senha incorretos. Tente novamente.</aside>}<button className="auth-link" onClick={reset}>Esqueci minha senha</button><button className="auth-primary" onClick={()=>setError(true)}>Entrar</button><button className="restaurant-access" onClick={restaurant}><Store/>Acesso para restaurantes</button>{error&&<button className="error-states-link" onClick={errors}>Ver estados de erro 6.7</button>}<button className="auth-demo" onClick={success}>Entrar como Marina (demo)</button><div className="auth-divider">ou</div><button className="social">Continuar com Google</button><button className="social">Continuar com Apple</button><p className="auth-bottom">Ainda não é cadastrado? <button onClick={signup}>Cadastre-se</button></p></AuthFrame> }
function Signup({ back, next }) { return <AuthFrame title="Crie sua conta" subtitle="Etapa 1 de 2 · conte um pouco sobre você." back={back}><div className="progress"><b/><i/></div><label className="auth-field">Nome<span><UserRound/><input placeholder="Seu nome"/></span></label><label className="auth-field">@username<span><AtSign/><input placeholder="ex.: mari.veg"/></span></label><label className="auth-field">E-mail<span><Mail/><input placeholder="voce@email.com" type="email"/></span></label><button className="auth-primary" onClick={next}>Continuar</button></AuthFrame> }
function SignupDetails({ back, confirm }) { return <AuthFrame title="Quase lá" subtitle="Etapa 2 de 2 · complete seu cadastro." back={back}><div className="progress"><b/><b/></div><label className="auth-field">Celular<span><Phone/><input placeholder="(41) 99999-9999"/></span></label><label className="auth-field">Cidade<span><MapPin/><input placeholder="Curitiba"/></span></label><label className="auth-field">Senha<span><Lock/><input type="password" placeholder="Crie uma senha"/></span></label><label className="check"><input type="checkbox"/> Li e aceito os Termos de Uso e a Política de Privacidade.</label><button className="auth-primary" onClick={confirm}>Criar conta</button></AuthFrame> }
function Verify({ confirmed }) { return <main className="shell"><section className="phone verify"><div><span><Mail/></span><h1>Confirme seu e-mail</h1><p>Enviamos um link para <b>marina@email.com</b>. Abra sua caixa de entrada para ativar sua conta.</p><button className="auth-primary" onClick={confirmed}>Já confirmei meu e-mail</button><button className="auth-link">Reenviar e-mail</button></div></section></main> }
function Reset({ back, sent }) { return <AuthFrame title="Recuperar senha" subtitle="Digite seu e-mail e enviaremos um link seguro." back={back}><label className="auth-field">E-mail<span><Mail/><input placeholder="voce@email.com" type="email"/></span></label><button className="auth-primary" onClick={sent}>Enviar link</button></AuthFrame> }
function ErrorStates({ back }) { const [kind,setKind]=useState('E-mail inválido'); const details={ 'E-mail inválido':['Digite um endereço de e-mail válido.','marina@email'], 'Senha incorreta':['E-mail ou senha incorretos. Tente novamente.','••••••••'], 'Cadastro — dados obrigatórios':['Preencha seu nome e escolha outro @username.','@marina.veg'], 'Cadastro incompleto':['Confira os campos destacados e aceite os termos para continuar.',''] }; return <AuthFrame title="Estados de erro" subtitle="6.7 · validações previstas para o fluxo de conta." back={back}><div className="error-tabs">{Object.keys(details).map(x=><button onClick={()=>setKind(x)} className={kind===x?'on':''} key={x}>{x.replace('Cadastro — ','')}</button>)}</div><aside className="auth-error">{details[kind][0]}</aside><label className="auth-field invalid">{kind.includes('Senha')?'Senha':kind.includes('E-mail')?'E-mail':'@username'}<span>{kind.includes('Senha')?<Lock/>:<AtSign/>}<input defaultValue={details[kind][1]}/></span><small>Revise esta informação antes de continuar.</small></label>{kind.includes('Cadastro')&&<label className="check invalid"><input type="checkbox"/> Li e aceito os Termos de Uso e a Política de Privacidade.</label>}<button className="auth-primary" onClick={back}>Voltar e corrigir</button></AuthFrame> }
function ScreenTop({ title, back }) { return <header className="form-top"><button onClick={back}><ArrowLeft/></button><h2>{title}</h2><span/></header> }
function Results({ mode, back, filters, detail, expired, market, empty, loading }) { const entries=[['Raízes Bistrô Vegano','4,9','Batel · 1,2 km','leaf',detail],['Casa Girassol','4,6','Juvevê · 2,1 km','sun',expired],['Empório Grão Livre','4,4','Batel · 1,6 km','peach',market]]; return <main className="shell"><section className="phone results-page"><ScreenTop title={mode==='map'?'Resultados no mapa':'Resultados'} back={back}/><div className="result-search"><Search/><b>vegano em Curitiba</b><button onClick={filters}><SlidersHorizontal/></button></div><nav className="result-switch"><button className={mode==='list'?'on':''} onClick={back}>Lista</button><button className={mode==='map'?'on':''} onClick={()=>loading('map')}>Mapa</button></nav>{mode==='map'?<div className="map-canvas"><Map/><button onClick={detail}>4,9<br/><small>Raízes</small></button><button onClick={market}>4,4<br/><small>Empório</small></button><button onClick={expired}>4,6<br/><small>Casa</small></button></div>:<div className="result-list"><p>24 lugares encontrados</p>{entries.map(([name,rating,meta,tone,open])=><button className="result-card" onClick={open} key={name}><Art tone={tone}/><span><b>{name}</b><Rating rating={rating} count="(94)"/><small>{meta}</small><Tags tags={name.includes('Empório')?['Mercado','Sem lactose']:['Vegano','Sem glúten']}/></span></button>)}<button className="text-action" onClick={empty}>Ver exemplo sem resultados</button></div>}</section></main> }
function Filters({ back, apply, empty }) { const [selected,setSelected]=useState(['Vegano']); const values=['Vegano','Vegetariano','Sem glúten','Sem lactose','Mercados']; const toggle=v=>setSelected(x=>x.includes(v)?x.filter(i=>i!==v):[...x,v]); return <main className="shell"><section className="phone filter-page"><ScreenTop title="Filtros" back={back}/><div className="filter-body"><h3>Preferências alimentares</h3><p>Encontre lugares compatíveis com você.</p><div className="select-tags">{values.map(v=><button className={selected.includes(v)?'selected':''} onClick={()=>toggle(v)} key={v}>{v}</button>)}</div><h3>Distância</h3><div className="filter-choice"><button>Até 2 km</button><button>Até 5 km</button><button>Qualquer distância</button></div><h3>Avaliação</h3><div className="filter-choice"><button>4 estrelas ou mais</button><button>3 estrelas ou mais</button></div></div><footer className="submit-bar"><button onClick={apply}>Ver 24 resultados</button><button className="filter-empty" onClick={empty}>Simular sem resultados</button></footer></section></main> }
function EmptyResults({ back, filters, map }) { return <main className="shell"><section className="phone empty-page"><ScreenTop title="Resultados" back={back}/><div><span><Search/></span><h1>Nenhum resultado encontrado</h1><p>Tente remover alguns filtros ou ampliar a distância de busca.</p><button className="auth-primary" onClick={filters}>Ajustar filtros</button><button className="auth-link" onClick={map}>Ver no mapa</button></div></section></main> }
function LoadingResults({ done }) { useEffect(()=>{const id=setTimeout(done,900);return()=>clearTimeout(id)},[done]); return <main className="shell"><section className="phone loading-page"><div><Leaf/><h2>Buscando lugares para você</h2><p>Considerando suas preferências alimentares.</p><i/><i/><i/></div></section></main> }
function AlternateDetail({ type, back, review }) { const market=type==='market'; return <main className="shell"><section className="phone alternate-detail"><ScreenTop title="Detalhes" back={back}/><Art tone={market?'peach':'sun'}/><div className="alternate-body"><span className={market?'market-label':'expired-label'}>{market?'Mercado e empório':'Selo precisa de atualização'}</span><h1>{market?'Empório Grão Livre':'Casa Girassol'}</h1><p>{market?'Produtos naturais, veganos e sem glúten.':'Restaurante vegetariano com opções veganas.'}</p><Rating rating={market?'4,4':'4,6'} count="(94)"/><Tags tags={market?['Mercado','Sem lactose']:['Vegetariano','Sem lactose']}/>{!market&&<aside>As informações de segurança alimentar ainda não foram confirmadas recentemente. Fale com o estabelecimento antes de visitar.</aside>}<button className="auth-primary" onClick={review}>Escrever avaliação</button></div></section></main> }
function BusinessFrame({ title='Cadastro do restaurante', step=0, back, action, actionLabel='Continuar', children }) { return <main className="shell"><section className="phone business-page"><ScreenTop title={title} back={back}/><div className="business-scroll">{step===0&&<div className="business-brand"><span><Leaf/></span><b>Vegetar</b><i>Para restaurantes</i></div>}{step>0&&<div className="biz-progress"><div>{[1,2,3,4,5].map(n=><i className={n<=step?'done':''} key={n}/>)}</div><small>Etapa {step} de 5</small></div>}{children}</div>{action&&<footer className="submit-bar"><button onClick={action}>{actionLabel}</button></footer>}</section></main> }
function BizField({ label, icon: Icon=Store, placeholder, type='text' }) { return <label className="auth-field"><span className="biz-label">{label}</span><span><Icon/><input type={type} placeholder={placeholder}/></span></label> }
function RestaurantLogin({ back, signup, panel }) { const [show,setShow]=useState(false); return <BusinessFrame title="Acesso da empresa" back={back}><section className="biz-intro"><h1>Seu restaurante no Vegetar</h1><p>Entre para atualizar seu perfil ou comece o cadastro completo da sua empresa.</p></section><div className="biz-flow-steps"><span>1. Dados</span><i/><span>2. Cardápio</span><i/><span>3. Perfil</span></div><div className="biz-form"><BizField label="E-mail" icon={Mail} placeholder="contato@restaurante.com"/><BizField label="Senha" icon={Lock} placeholder="Sua senha" type={show?'text':'password'}/><button className="auth-link" onClick={()=>setShow(!show)}>{show?'Ocultar senha':'Mostrar senha'}</button><button className="auth-primary" onClick={panel}>Entrar</button><button className="business-signup-cta" onClick={signup}><Store/>Cadastre seu restaurante</button><button className="restaurant-link" onClick={back}><UserRound/> Sou cliente, ir para o login de usuário</button></div><div className="biz-decor"><Carrot/><Apple/><Leaf/><Soup/></div></BusinessFrame> }
function BusinessSignup({ back, next }) { return <BusinessFrame title="Criar conta" back={back} action={next} actionLabel="Criar conta"><section className="biz-intro"><h1>Vamos começar</h1><p>Crie o acesso da pessoa responsável pelo estabelecimento.</p></section><div className="biz-form"><BizField label="Nome do responsável" icon={UserRound} placeholder="Seu nome completo"/><BizField label="E-mail" icon={Mail} placeholder="voce@empresa.com"/><BizField label="Celular" icon={Phone} placeholder="(41) 99999-9999"/><BizField label="Senha" icon={Lock} placeholder="Crie uma senha" type="password"/><label className="check"><input type="checkbox" defaultChecked/>Li e aceito os Termos de Uso para restaurantes.</label></div></BusinessFrame> }
const bizFields={identity:{heading:'Dados da empresa',copy:'Essas informações identificam o estabelecimento.',fields:[['Razão social',Store,'Nome registrado da empresa'],['Nome fantasia (aparece no app)',Store,'Como seus clientes conhecem'],['CNPJ',Store,'00.000.000/0001-00']]},address:{heading:'Onde vocês estão?',copy:'Use o endereço que será mostrado para os clientes.',fields:[['CEP',MapPin,'00000-000'],['Rua e número',MapPin,'Ex.: R. Mateus Leme, 123'],['Bairro',MapPin,'Seu bairro'],['Cidade / UF',MapPin,'Curitiba, PR']]},contact:{heading:'Como falar com vocês?',copy:'Informe canais públicos para clientes encontrarem o restaurante.',fields:[['Telefone do estabelecimento',Phone,'(41) 3333-3333'],['Site',Globe,'www.seurestaurante.com.br'],['Instagram',AtSign,'@seurestaurante'],['Outra rede social (opcional)',AtSign,'Link opcional']]}}
function BusinessData({ page, back, next }) { const data=bizFields[page]; const step={identity:1,address:2,contact:3}[page]; return <BusinessFrame step={step} back={back} action={next}><section className="biz-intro"><h1>{data.heading}</h1><p>{data.copy}</p></section><div className="biz-form">{data.fields.map(([label,icon,placeholder])=><BizField key={label} label={label} icon={icon} placeholder={placeholder}/>)}{page==='address'&&<><div className="mini-map"><Map/><b>Localização aproximada</b></div><aside className="biz-note"><MapPin/>Arraste o mapa para confirmar o ponto do seu endereço.</aside></>}</div></BusinessFrame> }
function BusinessType({ back, next }) { const [kind,setKind]=useState('Restaurante'); const [profile,setProfile]=useState('100% vegano'); const [days,setDays]=useState(['Terça','Quarta','Quinta','Sexta','Sábado','Domingo']); return <BusinessFrame step={4} back={back} action={next}><section className="biz-intro"><h1>Tipo, perfil e horário</h1></section><div className="biz-form"><section className="biz-group"><h3>Tipo de estabelecimento</h3><div className="select-tags">{['Restaurante','Mercado','Empório'].map(x=><button className={kind===x?'selected':''} onClick={()=>setKind(x)} key={x}>{x}</button>)}</div></section><section className="biz-group"><h3>Perfil do cardápio</h3><small>Escolha a opção que melhor descreve vocês.</small>{['100% vegano','100% vegetariano','Comum com opções veganas','Comum com opções vegetarianas'].map(x=><button className="biz-option" onClick={()=>setProfile(x)} key={x}><i className={profile===x?'radio on':'radio'}/>{x}</button>)}</section><section className="biz-group"><h3>Horário de funcionamento</h3>{['Segunda','Terça','Quarta','Quinta','Sexta','Sábado','Domingo'].map(x=><button className="day-row" onClick={()=>setDays(d=>d.includes(x)?d.filter(y=>y!==x):[...d,x])} key={x}><i className={days.includes(x)?'toggle on':'toggle'}/><b>{x}</b><small>{days.includes(x)?'11h às 22h':'Fechado'}</small></button>)}</section></div></BusinessFrame> }
function ClaimProfile({ back, next, fresh }) { const [method,setMethod]=useState('sms'); return <BusinessFrame step={5} back={back} action={next} actionLabel="Enviar código"><section className="biz-intro"><h1>Este é o seu restaurante?</h1><p>Encontramos um perfil que parece corresponder aos dados informados.</p></section><article className="claim-card"><Art tone="leaf"/><div><h3>Raízes Bistrô Vegano</h3><Rating rating="4,9" count="(128)"/><p>R. Mateus Leme, 123 · Curitiba</p><Tags tags={['Vegano','Sem glúten']}/></div></article><aside className="biz-note"><ShieldCheck/>As avaliações continuam da comunidade. Você poderá atualizar apenas as informações do perfil.</aside><section className="biz-group claim-options"><h3>Como prefere confirmar a posse?</h3>{[['sms','Código por SMS no telefone do estabelecimento'],['email','E-mail com o domínio do site'],['cnpj','Envio do cartão CNPJ para análise']].map(([id,label])=><button className="biz-option" onClick={()=>setMethod(id)} key={id}><i className={method===id?'radio on':'radio'}/>{label}</button>)}</section><button className="text-action" onClick={fresh}>Não é o meu restaurante, criar perfil novo</button></BusinessFrame> }
function ClaimCode({ back, next }) { return <BusinessFrame title="Confirmar posse" step={5} back={back} action={next} actionLabel="Confirmar código"><section className="biz-intro"><h1>Digite o código enviado</h1><p>Enviamos um código de seis dígitos para o telefone do estabelecimento.</p></section><div className="code-boxes">{[1,2,3,4,5,6].map(n=><input key={n} inputMode="numeric" maxLength="1" defaultValue={n<3?'•':''}/>)}</div><button className="auth-link code-link">Reenviar código em 00:42</button></BusinessFrame> }
function MenuForm({ back, next }) { const [allergens,setAllergens]=useState(['Oleaginosas','Soja','Gergelim']); const [care,setCare]=useState(['Área de preparo separada','Utensílios exclusivos','Equipe orientada']); const toggle=(v,set)=>set(a=>a.includes(v)?a.filter(x=>x!==v):[...a,v]); return <BusinessFrame title="Ficha do cardápio" back={back} action={next} actionLabel="Salvar ficha"><section className="biz-intro"><h1>Conte sobre o cardápio</h1><p>Esses dados ajudam pessoas com restrições a decidir com mais segurança.</p></section><aside className="how-card"><h3>Como preencher</h3><p>Seja claro sobre opções, alergênicos e cuidados no preparo.</p><p>As informações aparecerão na ficha pública do restaurante.</p></aside><div className="biz-form"><section className="biz-group"><h3>Pratos</h3><Counter label="Pratos veganos" initial={8}/><Counter label="Vegetarianos (não veganos)" initial={4}/></section><RadioGroup title="Opções sem glúten" selected="Alguns pratos" options={['Não oferecemos','Alguns pratos','Cardápio todo sem glúten']}/><RadioGroup title="Opções sem lactose" selected="Cardápio todo sem lactose" options={['Não oferecemos','Alguns pratos','Cardápio todo sem lactose']}/><section className="biz-group"><h3>Alérgenos presentes na cozinha</h3><div className="select-tags">{['Amendoim','Oleaginosas','Soja','Gergelim','Frutos do mar','Ovo'].map(x=><button onClick={()=>toggle(x,setAllergens)} className={allergens.includes(x)?'selected':''} key={x}>{x}</button>)}</div></section><section className="biz-group"><h3>Cuidados com contaminação cruzada</h3>{['Área de preparo separada','Utensílios exclusivos','Óleo de fritura exclusivo','Equipe orientada'].map(x=><button className="biz-option" onClick={()=>toggle(x,setCare)} key={x}><i className={care.includes(x)?'checkmark on':'checkmark'}/>{x}</button>)}</section><RadioGroup title="Flexibilidade do chef" selected="Adaptamos pratos quando o cliente avisa" options={['Adaptamos pratos quando o cliente avisa','Não fazemos alterações']}/></div></BusinessFrame> }
function Counter({ label, initial }) { const [n,setN]=useState(initial); return <div className="counter"><span>{label}</span><div><button onClick={()=>setN(Math.max(0,n-1))}>−</button><b>{n}</b><button onClick={()=>setN(n+1)}>+</button></div></div> }
function RadioGroup({ title, options, selected }) { const [value,setValue]=useState(selected); return <section className="biz-group"><h3>{title}</h3>{options.map(x=><button className="biz-option" onClick={()=>setValue(x)} key={x}><i className={value===x?'radio on':'radio'}/>{x}</button>)}</section> }
function PublicProfileForm({ back, next }) { return <BusinessFrame title="Perfil público" back={back} action={next} actionLabel="Pré-visualizar"><section className="biz-intro"><h1>Fotos e descrição</h1><p>Mostre o ambiente, os pratos e o que torna seu restaurante especial.</p></section><div className="biz-form"><section className="biz-group"><h3>Foto de capa</h3><small>Uma boa capa deixa seu perfil mais convidativo.</small><button className="cover-upload"><ImagePlus/>Adicionar foto de capa</button></section><PhotoGroup title="Ambiente" tone="sun"/><PhotoGroup title="Pratos" tone="leaf"/><label className="description-field">Descrição do restaurante<textarea defaultValue="Comida vegetariana afetiva, feita com ingredientes frescos e muito cuidado para receber cada pessoa."/><small>0 de 500 caracteres</small></label></div></BusinessFrame> }
function PhotoGroup({ title,tone }) { return <section className="biz-group"><h3>{title}</h3><div className="biz-photos"><Art tone={tone}/><Art tone={tone}/><button><ImagePlus/><small>Adicionar</small></button></div></section> }
function BusinessPreview({ back, next }) { return <main className="shell"><section className="phone preview-page"><header className="preview-banner"><span><Camera/>Pré-visualização do perfil</span><button onClick={back}>Editar</button></header><div className="preview-scroll"><div className="preview-hero"><Art tone="sun"/><button onClick={back}><ArrowLeft/></button></div><section className="preview-info"><span className="verified"><ShieldCheck/>Informações pela empresa</span><h1>Raízes Bistrô Vegano</h1><p>Restaurante vegano · Comida afetiva</p><p><MapPin/> R. Mateus Leme, 123 · Curitiba</p><p><Clock/><b>Aberto agora</b> · fecha às 22h</p><Rating rating="4,9" count="(128 avaliações)"/><Tags tags={['Vegano','Sem glúten']}/><div className="quick"><button><Heart/>Favoritar</button><button><Share2/>Compartilhar</button><button><Phone/>Ligar</button><button><Globe/>Site</button></div></section><section className="preview-safety"><h2><ShieldCheck/>Segurança alimentar</h2><p><b>Opções no cardápio</b><span>Confirmado</span></p><small>8 pratos veganos e opções sem glúten identificadas.</small><p><b>Contaminação cruzada</b><span>Com cuidados</span></p><small>Área separada e utensílios exclusivos informados pela empresa.</small></section></div><footer className="submit-bar"><button onClick={next}>Publicar e escolher plano</button></footer></section></main> }
function Plans({ back, done, interest }) { const [plan,setPlan]=useState('Freemium'); return <BusinessFrame title="Escolha de plano" back={back}><section className="biz-intro"><h1>Seu perfil está pronto!</h1><p>Escolha como quer começar. No piloto, nenhum valor será cobrado.</p></section><div className="plan-grid">{[['Freemium','60 dias de Premium grátis',['Perfil completo no app','Receba avaliações da comunidade','Teste recursos premium']],['Premium','Completo',['Destaque nas buscas','Dados e relatórios do perfil','Apoio para atualizar informações']]].map(([name,badge,items])=><button className={plan===name?'plan selected':'plan'} onClick={()=>setPlan(name)} key={name}><i>{badge}</i><h2>{name}</h2>{items.map(x=><p key={x}><CircleCheck/>{x}</p>)}</button>)}</div><aside className="biz-note"><CircleCheck/>Você pode mudar de plano depois. Nenhum recurso pago será cobrado durante o piloto.</aside><div className="plan-actions"><button className="auth-primary" onClick={done}>Começar teste grátis de 60 dias</button><button onClick={interest}>Tenho interesse no plano pago</button></div></BusinessFrame> }
function BusinessInterest({ back, done }) { return <main className="shell"><section className="phone sent-page"><div className="sent-content"><div className="sent-art"><div><CircleCheck size={54}/></div><Apple size={25}/><Carrot size={24}/></div><h1>Interesse registrado!</h1><p>Quando o plano pago estiver disponível, entraremos em contato. Enquanto isso, você já pode aproveitar 60 dias de Premium grátis.</p></div><footer className="sent-actions"><button onClick={done}>Começar teste grátis de 60 dias</button><button onClick={back}>Voltar aos planos</button></footer></section></main> }
function BusinessDone({ panel, home }) { return <main className="shell"><section className="phone sent-page"><div className="sent-content"><div className="sent-art"><div><CircleCheck size={54}/></div><Apple size={25}/><Carrot size={24}/><Leaf size={23}/></div><h1>Tudo pronto para crescer!</h1><p>Seu perfil foi publicado e já está disponível para a comunidade Vegetar.</p></div><footer className="sent-actions"><button onClick={panel}>Abrir painel</button><button onClick={home}>Ver meu perfil no app</button></footer></section></main> }
function BusinessPanel({ back }) {
  const [tab, setTab] = useState('overview')
  const [period, setPeriod] = useState('30 dias')
  const [reply, setReply] = useState(false)
  const nav = [['overview', 'Visão geral', ChartNoAxesCombined], ['reviews', 'Avaliações', MessageCircle], ['deals', 'Descontos', Ticket], ['profile', 'Perfil', Store], ['plan', 'Plano', Sparkles]]
  const Metric = ({ icon: Icon, label, value, change, muted }) => <article className={'dash-metric' + (muted ? ' locked' : '')}><span><Icon/></span><small>{label}</small><b>{value}</b><em>{muted ? <><Lock/> Premium</> : change}</em></article>
  const Review = ({ user, initials, stars, text, pending }) => <article className="dash-review"><span className="dash-avatar">{initials}</span><div><header><b>{user}</b><span className="dash-stars">{'★'.repeat(stars)}<i>{'★'.repeat(5 - stars)}</i></span></header><small>Há {pending ? '2 horas' : '1 dia'}</small><p>{text}</p>{pending ? <button onClick={() => setReply(!reply)}>{reply ? 'Fechar resposta' : 'Responder'}</button> : <em className="answered">Respondida</em>}{reply && pending && <textarea autoFocus placeholder="Escreva uma resposta pública…"/>}</div></article>
  const Overview = () => <>
    <section className="dash-identity"><span className="dash-place"><Store/></span><div><b>Raízes Bistrô Vegano</b><small>Teste Premium · 47 dias</small></div><button aria-label="Notificações"><Bell/><i/></button></section>
    <section className="dash-title"><p>Olá, Marina</p><h1>Visão geral</h1><small>Acompanhe os resultados do seu restaurante.</small></section>
    <section className="dash-metrics"><Metric icon={Eye} label="Visualizações" value="1.248" change="↗ 12%"/><Metric icon={Navigation} label="Como chegar" value="86" change="↗ 12%"/><Metric icon={Heart} label="Favoritos" value="312" change="↗ 8%"/><Metric icon={Star} label="Nota média" value="4,9" change="↗ 0,2"/></section>
    <section className="dash-card dash-chart"><header><div><h2>Popularidade</h2><small>Visitas e intenções de rota</small></div></header><div className="dash-period">{['7 dias', '30 dias', '90 dias'].map(item => <button key={item} className={period === item ? 'on' : ''} onClick={() => setPeriod(item)}>{item}</button>)}</div><div className="chart-legend"><span><i/>Visualizações</span><span><i/>Como chegar</span></div><svg viewBox="0 0 340 144" role="img" aria-label="Gráfico de popularidade"><path className="chart-grid" d="M20 20H332M20 52H332M20 84H332M20 116H332"/><path className="chart-area" d="M20 111 C52 94 62 95 88 74 S124 96 151 60 S184 69 212 45 S264 67 290 24 S318 34 332 19 L332 116 L20 116Z"/><path className="chart-green" d="M20 111 C52 94 62 95 88 74 S124 96 151 60 S184 69 212 45 S264 67 290 24 S318 34 332 19"/><path className="chart-orange" d="M20 119 C45 112 68 116 88 101 S127 112 151 92 S186 105 212 86 S254 96 290 73 S315 81 332 58"/><circle cx="290" cy="24" r="5"/></svg><div className="chart-dates"><span>11/10</span><span>25/10</span><span>09/11</span></div></section>
    <section className="dash-card dash-plan-mini"><small>SEU PLANO</small><h2>Premium em teste</h2><p><b>47 dias restantes</b><span>13 usados</span></p><i><b/></i><button onClick={() => setTab('plan')}>Ver planos</button></section>
    <section className="dash-card dash-recent"><header><div><h2>Avaliações recentes</h2><small>Interaja com sua comunidade</small></div><button onClick={() => setTab('reviews')}>Ver todas</button></header><Review user="@lu.vegana" initials="LV" stars={5} pending text="Comida incrível, atendimento muito atencioso!"/><Review user="@mari.semgluten" initials="MS" stars={5} text="Adorei as opções sem glúten."/></section>
  </>
  const Reviews = () => <><section className="dash-title compact"><p>Comunidade</p><h1>Avaliações</h1><small>412 avaliações · nota média 4,9</small></section><section className="dash-summary"><b>4,9 <Star/></b><span>412<br/><small>avaliações</small></span><span>94%<br/><small>respondidas</small></span></section><div className="dash-chips"><button className="on">Recentes</button><button>Pendentes (6)</button><button>Melhores</button></div><section className="dash-review-list"><Review user="@lu.vegana" initials="LV" stars={5} pending text="Comida incrível, atendimento muito atencioso!"/><Review user="@joao.veg" initials="JV" stars={3} pending text="Gostei, mas gostaria de mais opções no cardápio."/><Review user="@mari.semgluten" initials="MS" stars={5} text="Adorei as opções sem glúten."/></section></>
  const Deals = () => <><section className="dash-title compact"><p>Benefícios</p><h1>Descontos</h1><small>Crie vantagens para atrair novos clientes.</small></section><section className="dash-deal"><span><Ticket/></span><small>ATIVO ATÉ 30 NOV</small><h2>15% OFF no almoço</h2><p>Válido de terça a sexta, das 12h às 15h.</p><button>Editar desconto</button></section><section className="dash-empty"><Ticket/><h2>Criar novo desconto</h2><p>Ofereça uma vantagem exclusiva à comunidade Vegetar.</p><button className="auth-primary">Criar desconto</button></section></>
  const Profile = () => <><section className="dash-title compact"><p>Seu restaurante</p><h1>Perfil</h1><small>Mantenha suas informações sempre atualizadas.</small></section><section className="dash-card dash-profile-card"><div className="dash-cover"><Store/></div><h2>Raízes Bistrô Vegano</h2><p><MapPin/> Batel · Curitiba, PR</p><p><Clock/> Aberto hoje até 22h</p><button>Editar perfil</button></section><section className="dash-card dash-profile-list"><h2>Ficha do cardápio</h2><p><span>Pratos veganos</span><b>12</b></p><p><span>Opções sem glúten</span><b>6 pratos</b></p><p><span>Contaminação cruzada</span><b>Controlada</b></p><button>Editar ficha</button></section></>
  const Plan = () => <><section className="dash-title compact"><p>ASSINATURA</p><h1>Seu plano</h1><small>Aproveite todos os recursos para o seu negócio.</small></section><section className="dash-card dash-current"><small>PLANO ATUAL</small><h2>Teste Premium</h2><p>47 dias restantes de acesso completo</p><i><b/></i></section><section className="dash-plan-option"><em>60 dias grátis</em><h2>Premium</h2><p>Mais visibilidade, métricas completas e descontos para atrair clientes.</p><ul><li>Dados de desempenho</li><li>Cupons e descontos</li><li>Perfil em destaque</li></ul><button className="auth-primary">Tenho interesse no plano</button></section></>
  return <main className="shell"><section className="phone business-panel dashboard-mobile"><header className="dash-top"><div className="auth-logo"><Leaf/>Vegetar</div><button onClick={back} aria-label="Sair do painel"><LogOut/></button></header><main className="dash-scroll">{tab === 'overview' && <Overview/>}{tab === 'reviews' && <Reviews/>}{tab === 'deals' && <Deals/>}{tab === 'profile' && <Profile/>}{tab === 'plan' && <Plan/>}</main><nav className="dash-nav">{nav.map(([id, label, Icon]) => <button key={id} className={tab === id ? 'on' : ''} onClick={() => setTab(id)}><Icon/><small>{label}</small></button>)}</nav></section></main>
}
function EmailConfirmed({ home }) { return <main className="shell"><section className="phone verify"><div><span><CircleCheck/></span><h1>E-mail confirmado!</h1><p>Sua conta está pronta para encontrar e avaliar lugares incríveis.</p><button className="auth-primary" onClick={home}>Ir para a Home</button></div></section></main> }
function ResetSent({ back, resend }) { return <AuthFrame title="Link enviado" subtitle="Se o e-mail estiver cadastrado, você receberá um link para redefinir sua senha." back={back}><aside className="email-notice"><Mail/>Verifique também sua caixa de spam.</aside><button className="auth-primary" onClick={back}>Voltar ao login</button><button className="auth-link" onClick={resend}>Reenviar link</button></AuthFrame> }
function Profile({ home }) { const [tab,setTab]=useState('Avaliações'); return <main className="shell"><section className="phone profile"><header className="profile-top"><h1>Perfil</h1><Settings/></header><div className="profile-head"><div>MA</div><h2>Marina Alves</h2><p>@marina.veg · Curitiba, PR</p><small>E-mail verificado</small><section><b>12<em>avaliações</em></b><b>8<em>fotos</em></b><b>6<em>favoritos</em></b></section><button>Editar perfil</button></div><nav className="profile-tabs">{['Avaliações','Favoritos','Preferências'].map(item=><button className={tab===item?'on':''} onClick={()=>setTab(item)} key={item}>{item}</button>)}</nav><div className="profile-content">{tab==='Preferências'?<><h3>Minhas restrições</h3><Tags tags={['Vegano','Sem glúten']}/><h3>Alergias</h3><Tags tags={['Amendoim']}/><h3>Ajustes</h3><p>Aplicar minhas restrições nos filtros</p></>:<><h3>{tab==='Avaliações'?'Minhas avaliações':'Lugares favoritos'}</h3><p>{tab==='Avaliações'?'Você já ajudou 12 pessoas a encontrarem opções seguras.':'Seus lugares salvos aparecerão aqui.'}</p></>}</div><nav className="tabs"><button onClick={home}><House/>Início</button><button><Map/>Mapa</button><button><Heart/>Favoritos</button><button className="active"><UserRound/>Perfil</button></nav></section></main> }
function Detail({ back, review }) { const [saved,setSaved]=useState(false); return <main className="shell"><section className="phone detail"><div className="detail-scroll"><div className="detail-hero"><Art tone="leaf"/><div className="detail-nav"><button onClick={back}><ArrowLeft/></button><span/><button><Share2/></button><button onClick={()=>setSaved(!saved)} className={saved?'saved':''}><Heart fill={saved?'currentColor':'none'}/></button></div><div className="dots"><b/><i/><i/><i/><i/></div></div><p className="photo-note"><Camera/> Fotos enviadas pela comunidade</p><div className="thumbs"><div><Art tone="sun"/><b>Ambiente</b></div><div><Art tone="leaf"/><b>Pratos</b></div><div><Art tone="leaf"/><b>Cardápio</b></div></div><section className="detail-info"><div className="trustline"><Star fill="currentColor"/><span><ShieldCheck/>Verificado pela comunidade</span></div><h1>Raízes Bistrô Vegano</h1><p className="kitchen">Cozinha 100% vegana</p><p><MapPin/>R. Mateus Leme, 12 · São Francisco</p><p><Clock/><strong>Aberto</strong> · fecha às 22h</p><p><Ticket/>$$ · R$ 45 a 80 por pessoa</p><div className="big-rating"><b>4,9</b><span>★★★★★<small>412 avaliações</small></span></div><h3>Principais elogios</h3><Tags tags={['Cozinha separada','Equipe atenciosa','Bem sinalizado','Porções generosas']}/><div className="quick"><button><Heart/>Favoritar</button><button><Share2/>Compartilhar</button><button><Phone/>Ligar</button><button><Globe/>Site</button></div></section><section className="coupon"><Ticket/><div><small>OFERTA PARA A COMUNIDADE</small><b>10% de desconto no almoço</b><span>Código: VEGETAR10</span></div><button>Copiar</button></section><section className="safety"><h2><span><ShieldCheck/></span>Segurança alimentar</h2><div className="verified"><ShieldCheck/>Verificado pela comunidade</div><small>Última confirmação: há 12 dias</small>{[['Existência de pratos veganos','Cardápio amplo e identificado.'],['Contaminação cruzada','Equipe relata cuidado no preparo.'],['Flexibilidade do chef','Adapta pratos sob consulta.']].map(([a,b])=><article key={a}><div><b>{a}</b><span><CircleCheck/>Confirmado</span></div><p>{b}</p><small>Relatos da comunidade · atualizado recentemente</small></article>)}<aside>As informações são relatos da comunidade e podem mudar. Confirme com o estabelecimento em caso de alergias graves.</aside></section><section className="reviews"><h2>Avaliações</h2><div className="review-summary"><b>4,9</b><span>★★★★★<small>412 avaliações</small></span></div><button className="outline" onClick={review}>Escrever avaliação</button><div className="review"><div><b>MA</b><span><strong>Marina A.</strong><small>Há 2 semanas</small></span></div><em>★★★★★</em><p>Ambiente acolhedor e equipe muito atenciosa. Perguntaram sobre restrições e explicaram o cardápio inteiro.</p><Tags tags={['Sem glúten','Vegano']}/></div><div className="review"><div><b>LP</b><span><strong>Luiz P.</strong><small>Há 1 mês</small></span></div><em>★★★★★</em><p>Ótimas opções e porções generosas. Voltarei com certeza.</p><Tags tags={['Vegano']}/></div><button className="all-reviews">Ver todas as 412 avaliações</button></section></div><footer className="directions"><button><Navigation/>Como chegar</button></footer></section></main> }

export default function App() {
  const [screen, setScreen] = useState('splash'); const [category, setCategory] = useState(null); const [favorites, setFavorites] = useState([]); const [logged,setLogged] = useState(false); const [afterLoading,setAfterLoading] = useState('results')
  useEffect(() => { const id = setTimeout(() => setScreen('home'), 1600); return () => clearTimeout(id) }, [])
  const toggle = n => setFavorites(x => x.includes(n) ? x.filter(i => i !== n) : [...x, n])
  if (screen === 'splash') return <main className="shell"><section className="phone splash-phone"><Splash/><button className="skip" onClick={() => setScreen('home')}>Pular</button></section></main>
  if (screen === 'detail') return <DetailWithReport back={() => setScreen('home')} review={() => setScreen('review')}/>
  if (screen === 'review') return <Review back={() => setScreen('detail')} submitted={() => setScreen('review-sent')}/>
  if (screen === 'review-sent') return <ReviewSent restaurant={() => setScreen('detail')} home={() => setScreen('home')}/>
  if (screen === 'results') return <Results mode="list" back={() => setScreen('home')} filters={() => setScreen('filters')} detail={() => setScreen('detail')} expired={() => setScreen('expired')} market={() => setScreen('market')} empty={() => setScreen('empty')} loading={to => {setAfterLoading(`results-${to}`);setScreen('loading')}}/>
  if (screen === 'results-map') return <Results mode="map" back={() => setScreen('results')} filters={() => setScreen('filters')} detail={() => setScreen('detail')} expired={() => setScreen('expired')} market={() => setScreen('market')} empty={() => setScreen('empty')} loading={to => {setAfterLoading(`results-${to}`);setScreen('loading')}}/>
  if (screen === 'filters') return <Filters back={() => setScreen('results')} apply={() => setScreen('results')} empty={() => setScreen('empty')}/>
  if (screen === 'empty') return <EmptyResults back={() => setScreen('results')} filters={() => setScreen('filters')} map={() => setScreen('results-map')}/>
  if (screen === 'loading') return <LoadingResults done={() => setScreen(afterLoading)}/>
  if (screen === 'expired') return <AlternateDetail type="expired" back={() => setScreen('results')} review={() => setScreen('review')}/>
  if (screen === 'market') return <AlternateDetail type="market" back={() => setScreen('results')} review={() => setScreen('review')}/>
  if (screen === 'login') return <Login back={() => setScreen('home')} success={() => {setLogged(true);setScreen('profile')}} signup={() => setScreen('signup')} reset={() => setScreen('reset')} errors={() => setScreen('errors')} restaurant={() => setScreen('restaurant-login')}/>
  if (screen === 'signup') return <Signup back={() => setScreen('login')} next={() => setScreen('signup-details')}/>
  if (screen === 'signup-details') return <SignupDetails back={() => setScreen('signup')} confirm={() => setScreen('verify')}/>
  if (screen === 'verify') return <Verify confirmed={() => setScreen('email-confirmed')}/>
  if (screen === 'reset') return <Reset back={() => setScreen('login')} sent={() => setScreen('reset-sent')}/>
  if (screen === 'reset-sent') return <ResetSent back={() => setScreen('login')} resend={() => setScreen('reset')}/>
  if (screen === 'restaurant-login') return <RestaurantLogin back={() => setScreen('login')} signup={() => setScreen('business-signup')} panel={() => setScreen('business-panel')}/>
  if (screen === 'business-signup') return <BusinessSignup back={() => setScreen('restaurant-login')} next={() => setScreen('business-identity')}/>
  if (screen === 'business-identity') return <BusinessData page="identity" back={() => setScreen('business-signup')} next={() => setScreen('business-address')}/>
  if (screen === 'business-address') return <BusinessData page="address" back={() => setScreen('business-identity')} next={() => setScreen('business-contact')}/>
  if (screen === 'business-contact') return <BusinessData page="contact" back={() => setScreen('business-address')} next={() => setScreen('business-type')}/>
  if (screen === 'business-type') return <BusinessType back={() => setScreen('business-contact')} next={() => setScreen('business-claim')}/>
  if (screen === 'business-claim') return <ClaimProfile back={() => setScreen('business-type')} next={() => setScreen('business-code')} fresh={() => setScreen('business-menu')}/>
  if (screen === 'business-code') return <ClaimCode back={() => setScreen('business-claim')} next={() => setScreen('business-menu')}/>
  if (screen === 'business-menu') return <MenuForm back={() => setScreen('business-type')} next={() => setScreen('business-profile')}/>
  if (screen === 'business-profile') return <PublicProfileForm back={() => setScreen('business-menu')} next={() => setScreen('business-preview')}/>
  if (screen === 'business-preview') return <BusinessPreview back={() => setScreen('business-profile')} next={() => setScreen('business-plans')}/>
  if (screen === 'business-plans') return <Plans back={() => setScreen('business-preview')} done={() => setScreen('business-done')} interest={() => setScreen('business-interest')}/>
  if (screen === 'business-interest') return <BusinessInterest back={() => setScreen('business-plans')} done={() => setScreen('business-done')}/>
  if (screen === 'business-done') return <BusinessDone panel={() => setScreen('business-panel')} home={() => setScreen('detail')}/>
  if (screen === 'business-panel') return <BusinessPanel back={() => setScreen('home')}/>
  if (screen === 'email-confirmed') return <EmailConfirmed home={() => {setLogged(true);setScreen('home')}}/>
  if (screen === 'errors') return <ErrorStates back={() => setScreen('login')}/>
  if (screen === 'profile') return <Profile home={() => setScreen('home')}/>
  return <main className="shell"><section className="phone app">
    <header><button className="location"><MapPin size={22}/><span><small>Você está em</small><b>Curitiba <ChevronDown size={16}/></b></span></button><button className="login" onClick={() => setScreen(logged ? 'profile' : 'login')}><UserRound size={20}/>{logged ? 'Marina' : 'Entrar'}</button></header>
    <div className="searchbar"><button className="search" onClick={() => setScreen('results')}><Search size={22}/><span><b>Encontre seu próximo sabor</b><small>Restaurantes, mercados e empórios</small></span></button><button className="shortcut" onClick={() => setScreen('filters')}><SlidersHorizontal size={21}/></button><button className="shortcut" onClick={() => setScreen('results-map')}><Map size={21}/></button></div>
    <nav className="chips">{categories.map(([label, Icon]) => <button onClick={() => setCategory(category === label ? null : label)} className={category === label ? 'on' : ''} key={label}><Icon size={21}/>{label}</button>)}</nav>
    <div className="content"><section><div className="heading"><div><h2>Top restaurantes</h2><p>Mais amados pela comunidade</p></div><button onClick={() => setScreen('results')}>Ver todos <ArrowRight size={16}/></button></div><div className="ranking">{topPlaces.map(p => <ListCard key={p[0]} data={p} saved={favorites.includes(p[0])} save={() => toggle(p[0])} open={() => setScreen(p[0] === 'Casa Girassol' ? 'expired' : p[0] === 'Lótus Ramen' ? 'market' : 'detail')}/>)}</div></section>
    <section><div className="heading"><div><h2>Hits perto de você</h2><p>Opções para descobrir hoje</p></div><button onClick={() => setScreen('results-map')}>Ver mapa <Map size={16}/></button></div><div className="carousel">{nearby.map(p => <CarouselCard key={p[0]} data={p} saved={favorites.includes(p[0])} save={() => toggle(p[0])}/>)}</div></section><div className="divider"><span/><Leaf size={16}/><span/></div><section className="weekly"><div className="heading"><div><h2>Lugares para conhecer</h2><p>Uma seleção para esta semana</p></div></div><div className="banner"><Sparkles/><div><b>Novos sabores em Curitiba</b><p>Descubra locais inclusivos perto de você.</p></div></div></section></div>
    <nav className="tabs"><button className="active"><House/>Início</button><button><Map/>Mapa</button><button><Heart/>Favoritos</button><button onClick={() => setScreen(logged ? 'profile' : 'login')}><UserRound/>Perfil</button></nav>
    <aside className="legal"><span>🍃</span><p>Ao continuar, você concorda com nossos <b>Termos de Uso</b> e <b>Política de Privacidade</b>.</p><button>×</button></aside>
  </section><button className="restart" onClick={() => setScreen('splash')}>Rever abertura</button></main>
}
